import { useEffect, useState } from "react";

function useSearchMovies(query) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // First useEffect: API se movies fetch karega
  useEffect(() => {
    if (!query.trim()) {
      setData(null);
      setLoading(false);
      setError(null);
      return;
    }

    const fetchMovies = async () => {
      try {
        setLoading(true);
        setError(null);

        const response = await fetch(
          `https://www.omdbapi.com/?apikey=YOUR_API_KEY&s=${query}`
        );

        const result = await response.json();

        if (result.Response === "False") {
          throw new Error(result.Error || "Movie not found");
        }

        setData(result);
      } catch (err) {
        setError(err.message);
        setData(null);
      } finally {
        setLoading(false);
      }
    };

    fetchMovies();
  }, [query]);

  // Second useEffect: data change hone par console me message
  useEffect(() => {
    if (data) {
      console.log("Movie data has been updated:", data);
    }
  }, [data]);

  return {
    data,
    loading,
    error
  };
}

export default useSearchMovies;
